{"cmd":"cat > /Users/vincet/Documents/lpcsys/app.js <<'EOF'
const state = {
  models: [
    { id: "qwen3:8b", provider: "ollama", online: true },
    { id: "deepseek-r1:14b", provider: "ollama", online: true },
    { id: "gpt-4.1-mini", provider: "openai-compatible", online: true },
    { id: "embedding-nomic", provider: "ollama", online: false }
  ],
  agents: [
    { id: "research", name: "Research Agent", role: "Collect signal from docs/web", model: "qwen3:8b", x: 60, y: 60, temp: 0.2 },
    { id: "planner", name: "Planner Agent", role: "Task decomposition + PM constraints", model: "gpt-4.1-mini", x: 320, y: 130, temp: 0.3 },
    { id: "builder", name: "Builder Agent", role: "Generate implementation draft", model: "deepseek-r1:14b", x: 580, y: 75, temp: 0.4 },
    { id: "reviewer", name: "Reviewer Agent", role: "QA + policy check", model: "gpt-4.1-mini", x: 840, y: 140, temp: 0.1 }
  ],
  selectedAgentId: null
};

const modelListEl = document.getElementById("modelList");
const canvasEl = document.getElementById("canvas");
const inspectorEl = document.getElementById("inspector");
const timelineEl = document.getElementById("timeline");
const logEl = document.getElementById("log");

function log(message) {
  const time = new Date().toLocaleTimeString("zh-TW", { hour12: false });
  const line = document.createElement("div");
  line.className = "log-line";
  line.textContent = `[${time}] ${message}`;
  logEl.prepend(line);
}

function renderModels() {
  modelListEl.innerHTML = "";
  state.models.forEach((model) => {
    const li = document.createElement("li");
    li.className = "model-item";
    li.innerHTML = `
      <div>
        <code>${model.id}</code>
        <div class="hint">${model.provider}</div>
      </div>
      <button class="toggle ${model.online ? "" : "off"}">${model.online ? "online" : "offline"}</button>
    `;
    li.querySelector("button").addEventListener("click", () => {
      model.online = !model.online;
      renderModels();
      renderInspector();
      log(`model ${model.id} -> ${model.online ? "online" : "offline"}`);
    });
    modelListEl.appendChild(li);
  });
}

function renderCanvas() {
  canvasEl.innerHTML = "";
  drawLinks();

  state.agents.forEach((agent) => {
    const node = document.createElement("article");
    node.className = `agent-node ${state.selectedAgentId === agent.id ? "active" : ""}`;
    node.style.left = `${agent.x}px`;
    node.style.top = `${agent.y}px`;
    node.innerHTML = `
      <div class="agent-title">${agent.name}</div>
      <div class="agent-sub">${agent.role}</div>
      <div class="agent-sub">model: ${agent.model}</div>
    `;
    node.addEventListener("click", () => {
      state.selectedAgentId = agent.id;
      renderCanvas();
      renderInspector();
    });
    canvasEl.appendChild(node);
  });
}

function drawLinks() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("width", "100%");
  svg.setAttribute("height", "100%");
  svg.style.position = "absolute";
  svg.style.inset = "0";

  for (let i = 0; i < state.agents.length - 1; i++) {
    const a = state.agents[i];
    const b = state.agents[i + 1];
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    const x1 = a.x + 190;
    const y1 = a.y + 45;
    const x2 = b.x;
    const y2 = b.y + 45;
    const cx = (x1 + x2) / 2;
    path.setAttribute("d", `M ${x1} ${y1} C ${cx} ${y1}, ${cx} ${y2}, ${x2} ${y2}`);
    path.setAttribute("fill", "none");
    path.setAttribute("stroke", "#7d8da8");
    path.setAttribute("stroke-width", "2");
    path.setAttribute("stroke-dasharray", "5 5");
    svg.appendChild(path);
  }

  canvasEl.appendChild(svg);
}

function renderInspector() {
  const selected = state.agents.find((a) => a.id === state.selectedAgentId);
  if (!selected) {
    inspectorEl.textContent = "選擇一個 Agent 來編輯";
    return;
  }

  const modelOptions = state.models
    .map((m) => `<option value="${m.id}" ${m.id === selected.model ? "selected" : ""}>${m.id} ${m.online ? "" : "(offline)"}</option>`)
    .join("");

  inspectorEl.innerHTML = `
    <div class="group">
      <label>Agent Name</label>
      <input id="agentName" value="${selected.name}" />
    </div>
    <div class="group">
      <label>Model Binding</label>
      <select id="agentModel">${modelOptions}</select>
    </div>
    <div class="group">
      <label>Temperature (${selected.temp})</label>
      <input id="agentTemp" type="range" min="0" max="1" step="0.1" value="${selected.temp}" />
    </div>
    <button id="saveAgentBtn" class="accent">Save Agent Config</button>
  `;

  document.getElementById("saveAgentBtn").addEventListener("click", () => {
    selected.name = document.getElementById("agentName").value.trim() || selected.name;
    selected.model = document.getElementById("agentModel").value;
    selected.temp = Number(document.getElementById("agentTemp").value);
    renderCanvas();
    renderInspector();
    log(`agent ${selected.id} config updated`);
  });
}

function runSession() {
  const events = [];
  let totalTokens = 0;
  let totalCost = 0;
  let totalLatency = 0;

  state.agents.forEach((agent, index) => {
    const model = state.models.find((m) => m.id === agent.model);
    const tokens = 450 + Math.floor(Math.random() * 600);
    const latency = 280 + Math.floor(Math.random() * 850);
    const cost = model?.provider === "openai-compatible" ? tokens * 0.000002 : tokens * 0.0000006;

    totalTokens += tokens;
    totalCost += cost;
    totalLatency += latency;

    events.push(`${index + 1}. ${agent.name} on ${agent.model} -> ${tokens} tokens / ${latency} ms`);
  });

  timelineEl.innerHTML = events.map((line) => `<div>${line}</div>`).join("");
  document.getElementById("totalTokens").textContent = totalTokens.toLocaleString();
  document.getElementById("totalCost").textContent = `$${totalCost.toFixed(4)}`;
  document.getElementById("totalLatency").textContent = `${totalLatency} ms`;
  log("multi-agent session executed");
}

document.getElementById("addModelBtn").addEventListener("click", () => {
  const input = document.getElementById("modelNameInput");
  const id = input.value.trim();
  if (!id) return;
  if (state.models.some((m) => m.id === id)) {
    log(`model ${id} already exists`);
    return;
  }
  state.models.push({ id, provider: "ollama", online: true });
  input.value = "";
  renderModels();
  renderInspector();
  log(`model ${id} added`);
});

document.getElementById("runBtn").addEventListener("click", runSession);

// Demo hook: simulate invoking local product-manager skill
// and broadcasting constraints into planner agent.
document.getElementById("pmSkillBtn").addEventListener("click", () => {
  const planner = state.agents.find((a) => a.id === "planner");
  planner.role = "Task decomposition + outcomes over outputs + priority stack";
  renderCanvas();
  log("local skill invoked: product-manager -> planner constraints injected");
});

// Demo hook: simulate invoking local ui-designer-skill
// to apply theme presets for the whole interface.
document.getElementById("uiSkillBtn").addEventListener("click", () => {
  document.documentElement.style.setProperty("--accent", "#ab4f10");
  document.documentElement.style.setProperty("--accent-ink", "#532306");
  log("local skill invoked: ui-designer-skill -> warm contrast theme applied");
});

document.getElementById("clearLogBtn").addEventListener("click", () => {
  logEl.innerHTML = "";
});

renderModels();
renderCanvas();
renderInspector();
log("demo ready");
EOF"}

