.scene-header h1 {
  margin: 0;
  font-size: 1.03rem;
}

.hint {
  margin: 6px 0 14px;
  color: var(--muted);
  font-size: 0.86rem;
}

.model-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 8px;
}

.model-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dashed var(--line);
  padding-bottom: 8px;
}

.model-item code {
  font-family: \"IBM Plex Mono\", monospace;
  font-size: 0.82rem;
}

.toggle {
  font-size: 0.76rem;
  border-radius: 8px;
  padding: 5px 8px;
}

.toggle.off {
  background: #eee;
  color: #666;
}

.inline-form {
  margin-top: 12px;
  display: flex;
  gap: 6px;
}

input,
select {
  width: 100%;
  border-radius: 10px;
  border: 1px solid var(--line);
  padding: 9px 10px;
  font-family: inherit;
  background: #fff;
}

.center-stage {
  padding: 14px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 12px;
  min-height: 520px;
}

.scene-header p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 0.88rem;
}

.canvas {
  position: relative;
  border: 1px dashed #b7bfd0;
  border-radius: 14px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(13, 122, 95, 0.04), rgba(13, 122, 95, 0));
}

.agent-node {
  position: absolute;
  width: 190px;
  border: 1px solid #c9d4e4;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 12px;
  padding: 10px;
  cursor: pointer;
  transform-origin: center;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.agent-node:hover,
.agent-node.active {
  border-color: var(--accent);
  transform: scale(1.02);
}

.agent-title {
  font-weight: 700;
  font-size: 0.92rem;
}

.agent-sub {
  margin-top: 4px;
  font-size: 0.76rem;
  color: var(--muted);
}

.timeline {
  min-height: 64px;
  border-top: 1px solid var(--line);
  padding-top: 10px;
  font-family: \"IBM Plex Mono\", monospace;
  font-size: 0.78rem;
  color: #2f3e55;
}

.inspector {
  border: 1px dashed #bac4d5;
  border-radius: 12px;
  padding: 12px;
  min-height: 180px;
  font-size: 0.9rem;
  color: #2c2f3a;
}

.inspector .group {
  margin-bottom: 10px;
}

.inspector label {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
  margin-bottom: 4px;
}

.metrics {
  margin-top: 12px;
  display: grid;
  gap: 8px;
}

.metrics div {
  display: flex;
  justify-content: space-between;
  border-bottom: 1px dashed var(--line);
  padding-bottom: 8px;
}

.metrics span {
  color: var(--muted);
  font-size: 0.8rem;
}

.metrics strong {
  font-family: \"IBM Plex Mono\", monospace;
}

.log-panel {
  z-index: 1;
  padding: 12px 14px;
}

.log-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.log-head h3 {
  margin: 0;
  font-size: 0.95rem;
}

.log {
  margin-top: 10px;
  max-height: 140px;
  overflow: auto;
  font-family: \"IBM Plex Mono\", monospace;
  font-size: 0.76rem;
  line-height: 1.45;
}

.log-line {
  padding: 3px 0;
  border-bottom: 1px dotted #dce1eb;
}

@media (max-width: 1100px) {
  .shell {
    grid-template-columns: 1fr;
  }

  .center-stage {
    min-height: 440px;
  }

  .canvas {
    min-height: 280px;
  }
}
