      const state = {
        onlineKeys: {},
        agents: [
          { id: 1, name: 'Research Agent', role: 'Collect signal from docs/web', model: 'qwen3:8b' },
          { id: 2, name: 'Planner Agent', role: 'Task decomposition + PM constraints', model: 'gpt-4.1-mini' },
          { id: 3, name: 'Builder Agent', role: 'Generate implementation draft', model: 'claude-sonnet' },
          { id: 4, name: 'Reviewer Agent', role: 'QA + policy check', model: 'gpt-4.1-mini' }
