      .ambient { position:fixed; inset:0; pointer-events:none; background-image:linear-gradient(rgba(17,18,22,.03) 1px, transparent 1px),linear-gradient(90deg, rgba(17,18,22,.03) 1px, transparent 1px); background-size:28px 28px; mask-image:radial-gradient(circle at center, black 30%, transparent 100%); }
      .topbar { z-index:2; display:flex; justify-content:space-between; align-items:center; border:1px solid var(--line); backdrop-filter:blur(8px); background:var(--panel); border-radius:16px; padding:12px 16px; }
