      code { font-family:"IBM Plex Mono",monospace; font-size:.82rem; }
      .tag { font-size:.74rem; border-radius:8px; padding:4px 8px; border:1px solid var(--line); background:#fff; }
      .online-card { border:1px dashed #bac4d5; border-radius:10px; padding:10px; margin-bottom:8px; background:rgba(255,255,255,.62); }
      .card-top { display:flex; justify-content:space-between; align-items:center; gap:8px; }
      .api-btn { border:1px solid var(--line); border-radius:10px; padding:7px 10px; font-size:.75rem; background:#fff; cursor:pointer; }
      .api-status { margin-top:7px; font-size:.75rem; color:#405066; font-family:"IBM Plex Mono",monospace; }

      .center-stage { padding:14px; display:grid; grid-template-rows:auto 1fr auto; gap:12px; min-height:540px; }
      .canvas-viewport { border:1px dashed #b7bfd0; border-radius:14px; overflow:hidden; position:relative; background:linear-gradient(180deg, rgba(13,122,95,.04), rgba(13,122,95,0)); cursor:grab; }
      .canvas-viewport.dragging { cursor:grabbing; }
      .canvas-inner { position:absolute; inset:0; transform:translate(0px,0px); }
      .flow-svg { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; }
