      @media (max-width:1180px){ .shell{ grid-template-columns:1fr; } .center-stage{ min-height:460px; } .canvas-viewport{ min-height:280px; } }
    </style>
  </head>
  <body>
    <div class="ambient"></div>
    <header class="topbar">
      <div class="brand"><span class="dot"></span><span>Local Agent Ops</span></div>
      <div class="top-actions">
        <span class="pill" style="background:#0d7a5f;color:#fff;border-color:#0d7a5f;">Run Multi-Agent Session (Demo)</span>
      </div>
    </header>

    <main class="shell">
      <aside class="rail">
        <h2>Model Registry</h2>
        <p class="hint">Separate local runtimes and online providers</p>

        <div class="section-title">Local Models</div>
        <div class="model-item"><div><code>qwen3:8b</code><div class="hint">ollama</div></div><span class="tag">online</span></div>

        <div class="section-title">Online Models</div>

        <div class="online-card" data-model="gpt-4.1-mini">
          <div class="card-top">
            <div>
              <code>gpt-4.1-mini</code>
              <div class="hint">openai-compatible</div>
            </div>
            <button class="api-btn" data-model="gpt-4.1-mini">Add API Key</button>
          </div>
          <div class="api-status" id="status-gpt-4.1-mini">key: not set</div>
        </div>

        <div class="online-card" data-model="claude-sonnet">
          <div class="card-top">
            <div>
              <code>claude-sonnet</code>
              <div class="hint">anthropic-compatible</div>
            </div>
            <button class="api-btn" data-model="claude-sonnet">Add API Key</button>
          </div>
          <div class="api-status" id="status-claude-sonnet">key: not set</div>
        </div>
      </aside>

      <section class="center-stage">
        <div>
          <h1 style="font-size:1.03rem;">Multi-Agent Orchestration Canvas</h1>
          <p class="hint">Drag canvas with mouse; click + to add agent; double-click agent to rename</p>
        </div>

        <div class="canvas-viewport" id="canvasViewport">
          <div class="canvas-inner" id="canvasInner">
            <svg class="flow-svg" id="flowSvg"></svg>
          </div>
        </div>

        <div class="timeline" id="timeline"></div>
      </section>

      <aside class="rail">
        <h2>Inspector</h2>
        <p class="hint">Agent runtime binding and constraints</p>
        <div class="inspector" id="inspectorPanel"></div>
        <div class="metrics">
          <div><span>Total Tokens</span><strong style="font-family:'IBM Plex Mono',monospace;">2,890</strong></div>
          <div><span>Est. Cost</span><strong style="font-family:'IBM Plex Mono',monospace;">$0.0049</strong></div>
          <div><span>Latency</span><strong style="font-family:'IBM Plex Mono',monospace;">2,241 ms</strong></div>
        </div>
      </aside>
    </main>

    <section class="log-panel">
      <h3 style="font-size:.95rem;">Runtime Log</h3>
      <div class="log" id="runtimeLog"></div>
    </section>

    <div class="modal" id="apiModal" aria-hidden="true">
      <div class="modal-card">
        <div class="modal-head" id="modalTitle">Add API Key</div>
        <input class="input" id="apiKeyInput" placeholder="paste API key" />
        <div class="modal-actions">
          <button class="btn" id="cancelModalBtn">Cancel</button>
          <button class="btn accent" id="saveApiKeyBtn">Save Key</button>
        </div>
      </div>
    </div>

    <script>
      const state = {
        onlineKeys: {},
        agents: [
          { id: 1, name: 'Research Agent', role: 'Collect signal from docs/web', model: 'qwen3:8b', temperature: 0.2 },
          { id: 2, name: 'Planner Agent', role: 'Task decomposition + PM constraints', model: 'gpt-4.1-mini', temperature: 0.3 },
          { id: 3, name: 'Builder Agent', role: 'Generate implementation draft', model: 'claude-sonnet', temperature: 0.4 },
          { id: 4, name: 'Reviewer Agent', role: 'QA + policy check', model: 'gpt-4.1-mini', temperature: 0.1 }
        ],
        pan: { x: 0, y: 0 },
        activeModel: null,
        selectedAgentId: 2,
        nextAgentId: 5
      };

      const canvasViewport = document.getElementById('canvasViewport');
      const canvasInner = document.getElementById('canvasInner');
      const flowSvg = document.getElementById('flowSvg');
      const timeline = document.getElementById('timeline');
      const runtimeLog = document.getElementById('runtimeLog');
      const modal = document.getElementById('apiModal');
      const modalTitle = document.getElementById('modalTitle');
      const apiKeyInput = document.getElementById('apiKeyInput');
      const inspectorPanel = document.getElementById('inspectorPanel');

      function log(msg) {
        const time = new Date().toLocaleTimeString('zh-TW', { hour12: false });
        const line = document.createElement('div');
        line.className = 'log-line';
        line.textContent = `[${time}] ${msg}`;
        runtimeLog.prepend(line);
      }

      function mask(key) {
        if (!key) return 'not set';
        if (key.length < 8) return '*'.repeat(key.length);
        return key.slice(0, 4) + '*'.repeat(Math.max(6, key.length - 8)) + key.slice(-4);
      }

      function openApiModal(model) {
        state.activeModel = model;
        modalTitle.textContent = `Add API Key - ${model}`;
        apiKeyInput.value = '';
        modal.classList.add('open');
        apiKeyInput.focus();
      }

      function closeApiModal() {
        modal.classList.remove('open');
        state.activeModel = null;
      }

      function saveApiKey() {
        const key = apiKeyInput.value.trim();
        if (!key || !state.activeModel) return;
        state.onlineKeys[state.activeModel] = key;
        const status = document.getElementById(`status-${state.activeModel}`);
        if (status) status.textContent = `key: ${mask(key)}`;
        log(`API key saved for ${state.activeModel}`);
        closeApiModal();
      }

      function layoutAgents() {
        const startX = 60;
        const y = 120;
        const step = 260;
        state.agents = state.agents.map((agent, i) => ({ ...agent, x: startX + i * step, y }));
      }

      function renderCanvas() {
        layoutAgents();
        canvasInner.querySelectorAll('.node,.plus-btn').forEach((el) => el.remove());
        flowSvg.innerHTML = '';

        const viewportW = Math.max(canvasViewport.clientWidth, state.agents.length * 260 + 120);
        const viewportH = Math.max(canvasViewport.clientHeight, 320);
        flowSvg.setAttribute('viewBox', `0 0 ${viewportW} ${viewportH}`);

        state.agents.forEach((agent, idx) => {
          const node = document.createElement('article');
          node.className = 'node' + (state.selectedAgentId === agent.id ? ' active' : '');
          node.style.left = `${agent.x}px`;
          node.style.top = `${agent.y}px`;
          node.innerHTML = `<b>${agent.name}</b><small>${agent.role}</small><small>model: ${agent.model}</small>`;
          node.title = 'Double-click to rename';
          node.addEventListener('click', () => {
            state.selectedAgentId = agent.id;
            renderCanvas();
            renderInspector();
          });
          node.addEventListener('dblclick', () => renameAgent(agent.id));
          canvasInner.appendChild(node);

          if (idx < state.agents.length - 1) {
            const next = state.agents[idx + 1];
            const yMid = agent.y + 45;
            const x1 = agent.x + 190;
            const x2 = next.x;
            const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            line.setAttribute('x1', x1);
            line.setAttribute('y1', yMid);
            line.setAttribute('x2', x2);
            line.setAttribute('y2', yMid);
            line.setAttribute('stroke', '#7d8da8');
            line.setAttribute('stroke', '#7d8da8');
            line.setAttribute('stroke-width', '2');
            line.setAttribute('stroke-dasharray', '6 5');
            flowSvg.appendChild(line);

            const plus = document.createElement('button');
            plus.className = 'plus-btn';
            plus.textContent = '+';
            plus.style.left = `${(x1 + x2) / 2 - 14}px`;
            plus.style.top = `${yMid - 14}px`;
            plus.title = 'Add agent here';
            plus.addEventListener('click', () => insertAgent(idx + 1));
            canvasInner.appendChild(plus);
          }
        });

        renderTimeline();
      }

      function insertAgent(index) {
        const n = state.nextAgentId++;
        state.agents.splice(index, 0, {
          id: n,
          name: `New Agent ${n}`,
          role: 'Intermediate step',
          model: 'gpt-4.1-mini',
          temperature: 0.3
        });
        state.selectedAgentId = n;
        renderCanvas();
        renderInspector();
        log(`Inserted New Agent ${n} at step ${index + 1}`);
      }

      function renameAgent(agentId) {
        const target = state.agents.find((a) => a.id === agentId);
        if (!target) return;
        const nextName = window.prompt('Agent name:', target.name);
        if (!nextName) return;
        target.name = nextName.trim() || target.name;
        renderCanvas();
        renderInspector();
        log(`Renamed agent ${agentId} -> ${target.name}`);
      }

      function renderTimeline() {
        timeline.innerHTML = state.agents
          .map((a, i) => `<div>${i + 1}. ${a.name} -> model ${a.model}</div>`)
          .join('');
      }

      function renderInspector() {
        const agent = state.agents.find((a) => a.id === state.selectedAgentId);
        if (!agent) {
          inspectorPanel.innerHTML = '<div class="hint">Select an agent from canvas</div>';
          return;
        }
        const esc = (s) => String(s).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
        const modelOptions = ['qwen3:8b', 'gpt-4.1-mini', 'claude-sonnet']
          .map((m) => `<option value="${m}" ${m === agent.model ? 'selected' : ''}>${m}</option>`)
          .join('');
        inspectorPanel.innerHTML = `
          <div class="field"><label>Agent Name</label><input id="agentNameInput" value="${esc(agent.name)}" /></div>
          <div class="field"><label>Role</label><textarea id="agentRoleInput">${esc(agent.role)}</textarea></div>
          <div class="field"><label>Model Binding</label><select id="agentModelInput">${modelOptions}</select></div>
          <div class="field"><label>Temperature (0-1)</label><input id="agentTempInput" type="number" step="0.1" min="0" max="1" value="${agent.temperature ?? 0.3}" /></div>
          <button class="save-agent-btn" id="saveAgentBtn">Save Agent</button>
        `;
        document.getElementById('saveAgentBtn').addEventListener('click', () => {
          agent.name = document.getElementById('agentNameInput').value.trim() || agent.name;
          agent.role = document.getElementById('agentRoleInput').value.trim() || agent.role;
          agent.model = document.getElementById('agentModelInput').value;
          const t = Number(document.getElementById('agentTempInput').value);
          agent.temperature = Number.isFinite(t) ? Math.max(0, Math.min(1, t)) : (agent.temperature ?? 0.3);
          renderCanvas();
          renderInspector();
          log(`Updated ${agent.name}`);
        });
      }

      function applyPan() {
        canvasInner.style.transform = `translate(${state.pan.x}px, ${state.pan.y}px)`;
      }

      function setupCanvasDrag() {
        let dragging = false;
        let sx = 0;
        let sy = 0;

        canvasViewport.addEventListener('mousedown', (e) => {
          if (e.target.closest('.plus-btn') || e.target.closest('.node')) return;
          dragging = true;
          sx = e.clientX;
          sy = e.clientY;
          canvasViewport.classList.add('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          if (!dragging) return;
          state.pan.x += e.clientX - sx;
          state.pan.y += e.clientY - sy;
          sx = e.clientX;
          sy = e.clientY;
          applyPan();
        });

        window.addEventListener('mouseup', () => {
          dragging = false;
          canvasViewport.classList.remove('dragging');
        });
      }

      document.querySelectorAll('.api-btn').forEach((btn) => {
        btn.addEventListener('click', () => openApiModal(btn.dataset.model));
      });

      document.getElementById('cancelModalBtn').addEventListener('click', closeApiModal);
      document.getElementById('saveApiKeyBtn').addEventListener('click', saveApiKey);
      modal.addEventListener('click', (e) => { if (e.target === modal) closeApiModal(); });
      apiKeyInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') saveApiKey(); });

      setupCanvasDrag();
      renderCanvas();
      renderInspector();
      log('demo ready');
    </script>
  </body>
</html>

